// DeleteUniqueIndexCache 删除索引存在的缓存
func (s *SysPermissionRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.SysPermission) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, s.cache.Key(CacheSysPermissionByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[s.cache.Key(CacheSysPermissionByIDPrefix, item.ID)] = struct{}{}
			KeyMap[s.cache.Key(CacheSysPermissionByPathPrefix, item.Path)] = struct{}{}
			KeyMap[s.cache.Key(CacheSysPermissionByPidPrefix, item.Pid)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := s.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
